export function t(key,values={}){const source=messages[language][key]??messages.de[key]??key;return source.replace(/\{(\w+)\}/g,(_,name)=>values[name]??`{${name}}`);}
export function setLanguage(value){if(!Object.hasOwn(languages,value))return;language=value;try{if(globalThis.window)globalThis.localStorage?.setItem('utmref-language',value);}catch{}if(globalThis.document?.querySelectorAll){translatePage();globalThis.document.dispatchEvent(new Event('languagechange'));}}
export function translatePage(){document.documentElement.lang=language;const languageSelect=document.getElementById('language');if(languageSelect)languageSelect.value=language;const scales=document.getElementById('scale');if(scales)for(const option of scales.options)option.textContent='1 : '+Number(option.value).toLocaleString(language);for(const el of document.querySelectorAll('[data-i18n]'))el.textContent=t(el.dataset.i18n);for(const el of document.querySelectorAll('[data-i18n-html]'))el.innerHTML=t(el.dataset.i18nHtml);for(const el of document.querySelectorAll('[data-i18n-placeholder]'))el.placeholder=t(el.dataset.i18nPlaceholder);for(const el of document.querySelectorAll('[data-i18n-title]'))el.title=t(el.dataset.i18nTitle);for(const el of document.querySelectorAll('[data-i18n-alt]'))el.alt=t(el.dataset.i18nAlt);for(const el of document.querySelectorAll('[data-i18n-label]'))el.setAttribute('aria-label',t(el.dataset.i18nLabel));}

